from rules import active_dependencies, allowed


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    names = sorted(packages)
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    best = [None, None]

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    required = set(roots)

    def has_path(graph, start, goal):
        todo = [start]
        seen = set()
        while todo:
            node = todo.pop()
            if node == goal:
                return True
            if node in seen:
                continue
            seen.add(node)
            todo.extend(graph.get(node, ()))
        return False

    def search(assignments, expanded, limits, graph, needed):
        pending = sorted(needed - expanded)
        if not pending:
            score = tuple(assignments[n]['version'] if n in assignments else -1
                          for n in names)
            if best[0] is None or score > best[0]:
                best[0] = score
                best[1] = dict(assignments)
            return

        name = pending[0]
        if name not in assignments:
            rows = packages.get(name, [])
            candidates = sorted(rows, key=lambda row: row['version'], reverse=True)
            for row in candidates:
                version = row['version']
                if not allowed(name, version, limits, blocked, pins):
                    continue
                child_assignments = dict(assignments)
                child_assignments[name] = row
                search(child_assignments, set(expanded),
                       {key: list(value) for key, value in limits.items()},
                       {key: set(value) for key, value in graph.items()},
                       set(needed))
            return

        row = assignments[name]
        deps = active_dependencies(row.get('deps', []), features)
        new_limits = {key: list(value) for key, value in limits.items()}
        new_needed = set(needed)
        new_graph = {key: set(value) for key, value in graph.items()}
        new_graph.setdefault(name, set())

        for dep in deps:
            target = dep['name']
            low, high = dep['min'], dep['max']
            new_limits.setdefault(target, []).append((low, high))
            new_needed.add(target)
            if target in assignments and not all(
                    lo <= assignments[target]['version'] <= hi
                    for lo, hi in new_limits[target]):
                return
            if target == name or has_path(new_graph, target, name):
                return
            new_graph[name].add(target)

        new_expanded = set(expanded)
        new_expanded.add(name)
        search(dict(assignments), new_expanded, new_limits, new_graph, new_needed)

    search({}, set(), constraints, {}, required)
    if best[1] is None:
        return {'error': 'unsatisfiable'}
    return {'versions': {name: row['version'] for name, row in best[1].items()}}

def active_dependencies(deps, features):
    return [dep for dep in deps
            if not dep.get('feature') or dep.get('feature') in features]


def allowed(name, version, constraints, blocked, pins):
    if version in blocked.get(name, []):
        return False
    if name in pins and version != pins[name]:
        return False
    return all(low <= version <= high
               for low, high in constraints.get(name, []))
